const fs = require('fs');
const TOKEN = fs.readFileSync('/tmp/owner_token.txt', 'utf8').trim();
const https = require('https');
function get(path) {
  return new Promise((resolve) => {
    const req = https.request({ hostname: 'api.ivxholding.com', path, method: 'GET', headers: { 'Authorization': 'Bearer ' + TOKEN, 'Accept': 'application/json' }, timeout: 15000 }, res => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => { try { resolve({status: res.statusCode, ...JSON.parse(data)}); } catch(e) { resolve({status: res.statusCode, raw: data.slice(0,4000)}); } });
    });
    req.on('error', err => resolve({error: err.message}));
    req.end();
  });
}
(async () => {
  const r = await get('/api/ivx/render-diagnostic?limit=5');
  if (r.error) { console.log('ERROR:', r.error); return; }
  console.log('service plan:', r.serviceDetails?.plan);
  console.log('service suspended:', r.serviceDetails?.suspended);
  console.log('service type:', r.serviceDetails?.type);
  console.log('service autoDeploy:', r.serviceDetails?.autoDeploy);
  console.log('service name:', r.serviceDetails?.name);
  console.log('serviceId:', r.serviceDetails?.id);
  console.log('live SHA:', r.serviceDetails?.liveSha);
  console.log('');
  console.log('=== Recent deploys ===');
  if (r.deployments) {
    for (const d of r.deployments.slice(0, 5)) {
      console.log('Deploy:', d.id);
      console.log('  commit:', d.commit?.id);
      console.log('  status:', d.status);
      console.log('  failureReason:', d.failureReason || 'null');
      console.log('  createdAt:', d.createdAt);
      console.log('  finishedAt:', d.finishedAt);
    }
  }
  console.log('');
  console.log('=== Full JSON plan/suspended ===');
  console.log(JSON.stringify({ plan: r.serviceDetails?.plan, suspended: r.serviceDetails?.suspended, type: r.serviceDetails?.type, autoDeploy: r.serviceDetails?.autoDeploy }, null, 2));
})();
